CREATE EXTENSION IF NOT EXISTS vector;

-- IDs are UUIDv7 (time-ordered), generated by Postgres 18's built-in uuidv7().
CREATE TABLE IF NOT EXISTS users (
  id            UUID PRIMARY KEY DEFAULT uuidv7(),
  user_email    TEXT UNIQUE NOT NULL,      -- ON CONFLICT (user_email) needs this
  num_documents INT NOT NULL DEFAULT 0,
  plan          TEXT NOT NULL DEFAULT 'free',
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_signin   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS documents (
  id         UUID PRIMARY KEY DEFAULT uuidv7(),
  user_id    UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title      TEXT NOT NULL,
  url        TEXT NOT NULL,
  content    TEXT NOT NULL,
  embedding  vector,                      -- no fixed size, so a model change won't break inserts
  read       BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Every documents query filters by user_id; Postgres doesn't index FKs automatically.
CREATE INDEX IF NOT EXISTS documents_user_id_idx ON documents (user_id);
